package com.afkalert;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;
import net.runelite.client.config.Units;

@ConfigGroup(AfkAlertConfig.GROUP)
public interface AfkAlertConfig extends Config
{
	String GROUP = "afkalert";

	// ── Sections ───────────────────────────────────────────────────────────

	@ConfigSection(
		name = "Notification Settings",
		description = "Tray notification settings.",
		position = 5,
		closedByDefault = false
	)
	String notificationsSection = "notifications";

	// ── Timer ──────────────────────────────────────────────────────────────

	@ConfigItem(
		keyName = "timerDuration",
		name = "Timer duration",
		description = "Seconds of inactivity before the alert fires. Default 1140 = 19 min (just before the 20-min logout).",
		position = 0
	)
	@Range(min = 10, max = 1200)
	@Units(Units.SECONDS)
	default int timerDuration()
	{
		return 1140;
	}

	// ── Reset triggers ─────────────────────────────────────────────────────

	@ConfigItem(
		keyName = "resetOnXpDrop",
		name = "Reset on XP drop",
		description = "Resets the timer whenever the player gains XP (landed a hit or completed a skill action).",
		position = 1
	)
	default boolean resetOnXpDrop()
	{
		return false;
	}

	@ConfigItem(
		keyName = "resetOnHitsplat",
		name = "Reset on hitsplat received",
		description = "Resets the timer when the player takes damage (auto-retaliate would engage).",
		position = 2
	)
	default boolean resetOnHitsplat()
	{
		return false;
	}

	@ConfigItem(
		keyName = "resetOnMenuClick",
		name = "Reset on any player input",
		description = "Catch-all: resets the timer on any menu click or player-initiated action in the game world.",
		position = 3
	)
	default boolean resetOnMenuClick()
	{
		return true;
	}

	// ── Alerts ────────────────────────────────────────────────────────────

	@ConfigItem(
		keyName = "sendNotification",
		name = "Send tray notification",
		description = "Sends a RuneLite notification popup when the timer expires.",
		position = 0,
		section = notificationsSection
	)
	default boolean sendNotification()
	{
		return true;
	}

	@ConfigItem(
		keyName = "repeatNotification",
		name = "Repeat notification",
		description = "Re-fires the tray notification (and flashes the taskbar) repeatedly until you act.",
		position = 1,
		section = notificationsSection
	)
	default boolean repeatNotification()
	{
		return true;
	}

	@ConfigItem(
		keyName = "repeatInterval",
		name = "Repeat interval",
		description = "How often to re-fire the notification while you're still idle.",
		position = 2,
		section = notificationsSection
	)
	default RepeatInterval repeatInterval()
	{
		return RepeatInterval.SECONDS_30;
	}

	@ConfigItem(
		keyName = "showCountdown",
		name = "Show countdown timer",
		description = "Shows remaining time in the corner; blinks when the alert fires.",
		position = 4
	)
	default boolean showCountdown()
	{
		return true;
	}
}

package com.afkalert;

import com.google.inject.Provides;
import java.time.Duration;
import java.time.Instant;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.Notifier;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "AFK Alert",
	description = "Alerts you when you've been inactive too long; resets on combat actions that re-engage auto-retaliate.",
	tags = {"afk", "alert", "timer", "combat", "auto retaliate", "idle"}
)
public class AfkAlertPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private AfkAlertConfig config;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private AfkAlertOverlay overlay;

	private Instant lastActivity = Instant.now();

	private boolean alertFired = false;

	private Instant lastNotified = Instant.MIN;

	public boolean isAlertFired()
	{
		return alertFired;
	}

	@Override
	protected void startUp()
	{
		resetTimer();
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	public long secondsRemaining()
	{
		long elapsed = Duration.between(lastActivity, Instant.now()).getSeconds();
		return config.timerDuration() - elapsed;
	}

	public long millisRemaining()
	{
		long elapsed = Duration.between(lastActivity, Instant.now()).toMillis();
		return (long) config.timerDuration() * 1000 - elapsed;
	}

	void resetTimer()
	{
		lastActivity = Instant.now();
		alertFired = false;
		lastNotified = Instant.MIN;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (secondsRemaining() > 0)
		{
			return;
		}

		if (!alertFired)
		{
			alertFired = true;
			sendNotification();
			return;
		}

		if (config.repeatNotification()
			&& Duration.between(lastNotified, Instant.now()).getSeconds() >= config.repeatInterval().getSeconds())
		{
			sendNotification();
		}
	}

	private void sendNotification()
	{
		lastNotified = Instant.now();
		if (config.sendNotification())
		{
			notifier.notify("AFK Alert: you've been idle too long!");
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (config.resetOnXpDrop())
		{
			resetTimer();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!config.resetOnHitsplat())
		{
			return;
		}
		if (event.getActor() instanceof Player && event.getActor() == client.getLocalPlayer())
		{
			resetTimer();
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (config.resetOnMenuClick())
		{
			resetTimer();
		}
	}

	@Provides
	AfkAlertConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AfkAlertConfig.class);
	}
}

package com.afkalert;

public enum RepeatInterval
{
	SECONDS_15(15),
	SECONDS_30(30),
	SECONDS_60(60);

	private final int seconds;

	RepeatInterval(int seconds)
	{
		this.seconds = seconds;
	}

	public int getSeconds()
	{
		return seconds;
	}

	@Override
	public String toString()
	{
		return seconds + "s";
	}
}

package com.afkalert;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

public class AfkAlertOverlay extends OverlayPanel
{
	private static final int FLASH_PERIOD_MS = 600;
	private static final Color COUNTDOWN_SAFE = new Color(255, 255, 255, 180);
	private static final Color COUNTDOWN_WARN = new Color(255, 180, 0, 220);
	private static final Color COUNTDOWN_URGENT = new Color(255, 50, 50, 255);

	private final AfkAlertPlugin plugin;
	private final AfkAlertConfig config;

	@Inject
	AfkAlertOverlay(AfkAlertPlugin plugin, AfkAlertConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(AfkAlertOverlay.PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showCountdown())
		{
			return null;
		}

		panelComponent.getChildren().clear();

		if (plugin.isAlertFired())
		{
			long phase = (System.currentTimeMillis() / FLASH_PERIOD_MS) % 2;
			if (phase == 0)
			{
				return null;
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left("AFK!")
				.leftColor(COUNTDOWN_URGENT)
				.build());
		}
		else
		{
			long millis = plugin.millisRemaining();
			long totalSecs = millis / 1000;
			long mins = totalSecs / 60;
			long secs = totalSecs % 60;

			Color color = totalSecs <= 10 ? COUNTDOWN_URGENT
				: totalSecs <= 30          ? COUNTDOWN_WARN
				:                            COUNTDOWN_SAFE;

			String time;
			if (totalSecs <= 10)
			{
				long tenths = (millis % 1000) / 100;
				time = String.format("%d:%02d.%d", mins, secs, tenths);
			}
			else
			{
				time = String.format("%d:%02d", mins, secs);
			}

			panelComponent.getChildren().add(LineComponent.builder()
				.left("AFK")
				.right(time)
				.rightColor(color)
				.build());
		}

		return super.render(g);
	}
}
